-- 036: Kassenbuch cũ (Excel) tháng 01–10/2026 của Vietbowl Mitte, chỉ để xem (người dùng chốt 2026-11-27).
-- App tính Kassenbuch theo cách mới từ 01.11.2026: opening_date = 2026-11-01, opening_cash = Saldo 31.10.2026.
create table if not exists public.nh_kb_legacy (
  id bigserial primary key,
  restaurant_id uuid not null references public.nh_restaurants(id) on delete cascade,
  period text not null,
  pos int not null,               -- 0 = dòng Saldo đầu tháng
  entry_date date not null,
  beleg text, ein numeric(12,2) not null default 0, aus numeric(12,2) not null default 0,
  mwst text, ust numeric(12,2), vst numeric(12,2), ein_netto numeric(12,2), aus_netto numeric(12,2),
  saldo numeric(12,2), text text,
  unique (restaurant_id, period, pos)
);
alter table public.nh_kb_legacy enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where tablename = 'nh_kb_legacy' and policyname = 'nh_kbl_sel') then
    create policy nh_kbl_sel on public.nh_kb_legacy for select to authenticated using (public.nh_can_manage(restaurant_id));
  end if;
end $$;
grant select on public.nh_kb_legacy to authenticated;

on conflict (restaurant_id, period, pos) do update set entry_date=excluded.entry_date, beleg=excluded.beleg, ein=excluded.ein, aus=excluded.aus, mwst=excluded.mwst, ust=excluded.ust, vst=excluded.vst, ein_netto=excluded.ein_netto, aus_netto=excluded.aus_netto, saldo=excluded.saldo, text=excluded.text;

-- Kassenbuch trong app bắt đầu 01.11.2026, tồn quỹ đầu = Saldo 31.10.2026 theo Excel
update public.nh_restaurants set opening_date = '2026-11-01', opening_cash = 20217.16 where id = 'b9ebdf92-a0aa-4033-a715-7f57af23900a';
